                thread?: components["parameters"]["StatsThreadQuery"];
                /** @description 只统计该模型（`<provider>/<model>`）；生效时 `toolCalls` / `toolErrors` / `turns` 为 0 */
                model?: components["parameters"]["StatsModelQuery"];
